{"command":"cat > /tmp/sysroot_types.py << 'PY'
import subprocess, os, pathlib, shutil
base=pathlib.Path.home()/".rustowl/sysroot/nightly-2025-06-20-x86_64-unknown-linux-gnu"
def clean(): shutil.rmtree(pathlib.Path.home()/".rustowl",ignore_errors=True)
def run(cmd):
    r=subprocess.run(["/workspace/executable"]+cmd,capture_output=True,text=True,timeout=15,cwd="/tmp/proj1")
    print(cmd,"exit",r.returncode,"err",r.stderr[:2000])
for kind in ["none","dir","file","symlink_dir","symlink_file","symlink_broken","fifo"]:
    clean(); base.parent.mkdir(parents=True,exist_ok=True)
    if kind=="dir": base.mkdir()
    elif kind=="file": base.write_text("x")
    elif kind=="symlink_dir": pathlib.Path("/tmp/realsys").mkdir(exist_ok=True); base.symlink_to("/tmp/realsys",target_is_directory=True)
