# Fake HTTPS via proxy server utilities
import socket, ssl, threading, time, os, subprocess, pathlib, tarfile, io
class FakeServer:
    def __init__(self, routes, port=18081):
        """routes: dict host->dict path-> body bytes or (status, headers, body) or callable"""
        self.routes=routes; self.port=port; self.requests=[]; self.stop=False
    def start(self):
        self.th=threading.Thread(target=self._run,daemon=True); self.th.start(); time.sleep(0.2); return self
    def _run(self):
        self.sock=socket.socket(); self.sock.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); self.sock.bind(("127.0.0.1",self.port)); self.sock.listen(20); self.sock.settimeout(1)
        while not self.stop:
            try: c,a=self.sock.accept()
            except socket.timeout: continue
            threading.Thread(target=self._handle,args=(c,),daemon=True).start()
    def _handle(self,c):
        try:
            data=c.recv(8192)
            # CONNECT host:443
            first=data.split(b"\r\n")[0].decode(); print("CONNECTLINE",first)
            host=first.split()[1].rsplit(":",1)[0] if len(first.split())>=2 else ""
            c.sendall(b"HTTP/1.1 200 Connection Established\r\n\r\n")
            # choose cert based on host - need cert file for each host generated beforehand in /tmp/tls/<host>.crt/key if exists else static cert
            cert=f"/tmp/tls/{host}.crt"; key=f"/tmp/tls/{host}.key"
            if not os.path.exists(cert): cert="/tmp/tls/server.crt"; key="/tmp/tls/server.key"
            ctx=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER); ctx.load_cert_chain(cert,key)
            tls=ctx.wrap_socket(c,server_side=True)
            # loop requests on same connection (HTTP/1.1 keepalive)
            tls.settimeout(3)
            buf=b""
            try:
                while True:
                    while b"\r\n\r\n" not in buf:
                        chunk=tls.recv(8192)
                        if not chunk: raise ConnectionError("eof")
                        buf+=chunk
                    head,buf=buf.split(b"\r\n\r\n",1)
                    lines=head.decode(errors='replace').split("\r\n"); method,path,ver=lines[0].split()
                    headers={k.lower():v.strip() for k,v in (x.split(":",1) for x in lines[1:] if ":" in x)}
                    self.requests.append((host,method,path,headers)); print("REQ",host,method,path,headers)
                    route=self.routes.get(host,{}).get(path)
                    if route is None: route=self.routes.get("*",{}).get(path)
                    if callable(route): status,hdrs,body=route(host,path,headers)
                    elif isinstance(route,tuple): status,hdrs,body=route
                    elif route is not None: status,hdrs,body=200,{},route
                    else: status,hdrs,body=404,{},b"not found"
                    if isinstance(body,str): body=body.encode()
                    resp=f"HTTP/1.1 {status} X\r\nContent-Length: {len(body)}\r\n".encode()
                    for k,v in hdrs.items(): resp+=f"{k}: {v}\r\n".encode()
                    resp+=b"\r\n"+body
                    tls.sendall(resp)
                    if headers.get("connection")=="close": break
            except Exception as e:
                #print("conn end",e)
                pass
            tls.close()
        except Exception as e:
            print("handle err",repr(e)); 
            try:c.close()
            except:pass
    def close(self):
        self.stop=True
        try:self.sock.close()
        except:pass

def make_targz(files):
    """files dict arcname->bytes or (bytes,mode)"""
    bio=io.BytesIO()
    with tarfile.open(fileobj=bio,mode="w:gz") as tf:
        for name,data in files.items():
            if isinstance(data,tuple): data,mode=data
            else: mode=0o644
            ti=tarfile.TarInfo(name); ti.size=len(data); ti.mode=mode; ti.mtime=0
            tf.addfile(ti,io.BytesIO(data))
    return bio.getvalue()
def env():
    e=os.environ.copy(); e.update({"HTTPS_PROXY":"http://127.0.0.1:18081","https_proxy":"http://127.0.0.1:18081","SSL_CERT_FILE":"/tmp/tls/ca.crt"}); return e
