# ---------------------------------------------------------------------------
# small utility helpers

def fs_str(path):
    """Return a filesystem string (surrogateescape-preserved)."""
    return os.fsdecode(os.fspath(path))

def display_path(path):
    """Rust Path::display semantics (lossy UTF-8)."""
    s = fs_str(path)
    b = os.fsencode(s)
    return b.decode("utf-8", "replace")

def rust_str_debug(s):
    """Approximate Rust {:?} for a string (used in a few error messages)."""
    out = '"'
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out += '\\"'
        elif ch == "\\":
            out += "\\\\"
        elif ch == "\n":
            out += "\\n"
        elif ch == "\r":
            out += "\\r"
        elif ch == "\t":
            out += "\\t"
        elif o < 0x20 or o == 0x7f:
            out += f"\\u{{{o:x}}}"
        else:
            out += ch
    return out + '"'

def rust_bytes_debug(b):
    if isinstance(b, str):
        b = b.encode()
    # Rust Debug for a byte-string slice: b"..." with \xNN escapes.
    out = 'b"'
    for x in b:
        if x == 0x22:
            out += '\\"'
        elif x == 0x5c:
            out += "\\\\"
        elif x == 0x0a:
            out += "\\n"
        elif x == 0x0d:
            out += "\\r"
        elif x == 0x09:
            out += "\\t"
        elif 0x20 <= x <= 0x7e:
            out += chr(x)
        else:
            out += f"\\x{x:02x}"
    return out + '"'

def path_join(base, *parts):
    # os.path.join discards the base for absolute parts, matching PathBuf::join.
    p = fs_str(base)
    for part in parts:
        part = fs_str(part)
        if p == "":
            p = part
        elif part.startswith("/"):
            p = part
        else:
            p = p.rstrip("/") + "/" + part if p != "/" else "/" + part
