            url = f"https://static.rust-lang.org/dist/{TOOLCHAIN_DATE}/{top}.tar.gz"
            if not download_and_unpack(url, tempdir):
                return False
            comp_list = os.path.join(tempdir, top, "components")
            try:
                with open(comp_list, "r", encoding="utf-8") as f:
                    content = f.read()
            except Exception:
                log_error("rustowl::toolchain", "failed to read components list")
                return False
            for line in content.splitlines():
                src = os.path.join(tempdir, top, line)
                _copy_dir_recursive(src, sysroot)
                log_info("rustowl::toolchain", f"component {line} successfully installed")
        finally:
            shutil.rmtree(tempdir, ignore_errors=True)
    log_info("rustowl::toolchain", "installing Rust toolchain finished")
    return True

def setup_toolchain(runtime_opt=None):
    if not install_rust_toolchain(runtime_opt):
        return False
    runtime = fs_str(runtime_opt) if runtime_opt is not None else get_runtime_dir()
    log_info("rustowl::toolchain", "start installing RustOwl toolchain...")
    url = (f"https://github.com/cordx56/rustowl/releases/download/{VERSION}/"
           f"rustowl-{TARGET_TRIPLE}.tar.gz")
    if runtime is not None and download_and_unpack(url, runtime):
        log_info("rustowl::toolchain", "installing RustOwl toolchain finished")
    else:
        if runtime is None:
            # download_and_unpack was not attempted; still warn below
            pass
        log_warn("rustowl::toolchain", "could not install RustOwl toolchain; local installed rustowlc will be used")
    log_info("rustowl::toolchain", "toolchain setup finished")
    return True

def ensure_toolchain_or_exit():
    if get_sysroot() is None:
        log_info("rustowl::toolchain", "sysroot not found; start setup toolchain")
        if not setup_toolchain(None):
            log_error("rustowl::toolchain", "()")
            # Flush stdio before exiting abruptly like the reference does.
            try:
                sys.stderr.buffer.flush()
            except Exception:
                pass
            os._exit(1)

def toolchain_uninstall():
    sysroot = get_sysroot()
    if sysroot is not None:
        log_info("rustowl::toolchain", f"remove sysroot: {display_path(sysroot)}")
        try:
            if os.path.islink(sysroot):
                os.unlink(sysroot)
            else:
                shutil.rmtree(sysroot)
        except OSError as e:
            rust_panic("main", "/workspace/src/toolchain.rs:237:40",
                       f"called `Result::unwrap()` on an `Err` value: {os_error_debug(e)}")
            os._exit(101)
    return 0

