# ---------------------------------------------------------------------------
# HTTP downloading (reqwest-like behaviour / error formatting)

class ReqwestError(Exception):
    def __init__(self, debug):
        super().__init__(debug)
        self.debug = debug

def _reqwest_request_error(url, source):
    return ReqwestError(
        f'reqwest::Error {{ kind: Request, url: {rust_str_debug(url)}, source: {source} }}')

def _dns_source(e):
    msg = e.strerror or str(e)
    # getaddrinfo message from libc is already e.g. "Temporary failure ..."
    inner = f"failed to lookup address information: {msg}"
    return ('hyper_util::client::legacy::Error(Connect, ConnectError("dns error", '
            f'Custom {{ kind: Uncategorized, error: {rust_str_debug(inner)} }}))')

def _tcp_source(addr, e):
    inner = os_error_debug(e)
    return ('hyper_util::client::legacy::Error(Connect, ConnectError("tcp connect error", '
            f'{addr}, {inner}))')

def _io_source(e):
    return f'hyper_util::client::legacy::Error(Connect, Io({os_error_debug(e)}))'

def _parse_url(url):
    m = re.match(r"^([A-Za-z][A-Za-z0-9+.-]*)://([^/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$", url)
    if not m:
        return None
    scheme, authority, path, query, _frag = m.groups()
    if "@" in authority:
        authority = authority.rsplit("@", 1)[1]
    host = authority
    port = None
    if authority.startswith("["):
        end = authority.find("]")
        host = authority[1:end]
        rest = authority[end + 1:]
        if rest.startswith(":"):
            port = int(rest[1:])
    elif ":" in authority:
        host, p = authority.rsplit(":", 1)
        if p.isdigit():
            port = int(p)
    if not path:
        path = "/"
    return scheme.lower(), host, port, path + (query or "")

def _proxy_for(scheme, host):
    no_proxy = os.environ.get("NO_PROXY") or os.environ.get("no_proxy") or ""
    for item in no_proxy.split(","):
        item = item.strip().lower()
        if item and (host.lower() == item or host.lower().endswith("." + item.lstrip(".")) or item == "*"):
            return None
    if scheme == "https":
        proxy = os.environ.get("HTTPS_PROXY") or os.environ.get("https_proxy")
    else:
        proxy = os.environ.get("HTTP_PROXY") or os.environ.get("http_proxy")
    if not proxy:
        proxy = os.environ.get("ALL_PROXY") or os.environ.get("all_proxy")
    return proxy or None

def _parse_proxy(proxy):
    if "://" not in proxy:
        proxy = "http://" + proxy
    m = re.match(r"^([A-Za-z][A-Za-z0-9+.-]*)://(?:([^/@]*?)@)?([^/?#]*)(/.*)?$", proxy)
    if not m:
        return None
    scheme, userinfo, authority, _p = m.groups()
    host = authority
    port = 8080
    if authority.startswith("["):
        end = authority.find("]")
        host = authority[1:end]
        rest = authority[end + 1:]
        if rest.startswith(":") and rest[1:].isdigit():
            port = int(rest[1:])
    elif ":" in authority:
        host, p = authority.rsplit(":", 1)
        if p.isdigit():
            port = int(p)
    auth = None
    if userinfo:
        import base64
        auth = base64.b64encode(userinfo.encode()).decode()
    return host, port, auth

def _read_until(sock_file, marker=b"\r\n\r\n", limit=65536):
    data = b""
    while marker not in data and len(data) < limit:
        chunk = sock_file.read1(4096) if hasattr(sock_file, "read1") else sock_file.recv(4096)
        if not chunk:
            break
        data += chunk
    return data

def _connect_tcp(url, host, port):
    try:
        infos = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
    except socket.gaierror as e:
        raise _reqwest_request_error(url, _dns_source(e))
    last = None
    for family, stype, proto, _canon, sockaddr in infos:
        s = socket.socket(family, stype, proto)
        try:
            s.settimeout(30)
            s.connect(sockaddr)
            return s
        except OSError as e:
            last = (sockaddr, e)
            try:
                s.close()
            except Exception:
                pass
    sockaddr, e = last if last else ((host, port), OSError("no address"))
    if len(sockaddr) >= 2:
        addr = f"{sockaddr[0]}:{sockaddr[1]}"
    else:
        addr = str(sockaddr)
    raise _reqwest_request_error(url, _tcp_source(addr, e))

def _http_request_once(url, out_chunks):
    parsed = _parse_url(url)
    if not parsed:
        raise _reqwest_request_error(url, "builder error")
    scheme, host, port, path = parsed
    is_https = scheme == "https"
    if port is None:
        port = 443 if is_https else 80
    log_debug("reqwest::connect", f"starting new connection: {scheme}://{host}/")
    proxy = _proxy_for(scheme, host)
    sock = None
    if proxy and is_https:
        pp = _parse_proxy(proxy)
        if pp:
            phost, pport, auth = pp
            sock = _connect_tcp(url, phost, pport)
            target = f"{host}:{port}"
            req = f"CONNECT {target} HTTP/1.1\r\nHost: {target}\r\n"
            if auth:
                req += f"Proxy-Authorization: Basic {auth}\r\n"
            req += "\r\n"
            try:
                sock.sendall(req.encode())
                buf = b""
                sock.settimeout(10)
                while b"\r\n\r\n" not in buf and len(buf) < 16384:
                    chunk = sock.recv(4096)
                    if not chunk:
                        break
                    buf += chunk
            except OSError as e:
                raise _reqwest_request_error(
                    url, 'hyper_util::client::legacy::Error(Connect, TunnelUnsuccessful)')
            status_line = buf.split(b"\r\n", 1)[0] if buf else b""
            parts = status_line.split(b" ")
            if len(parts) < 2 or not parts[1].isdigit() or not (200 <= int(parts[1]) < 300):
                try:
                    sock.close()
                except Exception:
                    pass
                raise _reqwest_request_error(
                    url, 'hyper_util::client::legacy::Error(Connect, TunnelUnsuccessful)')
    elif proxy and not is_https:
        pp = _parse_proxy(proxy)
        if pp:
            phost, pport, auth = pp
            sock = _connect_tcp(url, phost, pport)
            req_path = url
            extra = f"Proxy-Authorization: Basic {auth}\r\n" if auth else ""
            req = f"GET {req_path} HTTP/1.1\r\naccept: */*\r\nhost: {host}\r\n{extra}\r\n"
            sock.sendall(req.encode())
            return _read_response(url, sock, out_chunks)
    if sock is None:
        sock = _connect_tcp(url, host, port)
    raw = sock
    if is_https:
        ctx = ssl.create_default_context()
        # OpenSSL (and thus Python) honours SSL_CERT_FILE/SSL_CERT_DIR in the
        # default verify paths, matching rustls-native-certs closely enough.
        try:
            sock = ctx.wrap_socket(sock, server_hostname=host)
        except ssl.SSLCertVerificationError as e:
            msg = str(e)
            if "Hostname mismatch" in msg or "hostname" in msg.lower():
                inner = (f'Custom {{ kind: InvalidData, error: InvalidCertificate(NotValidForName) }}')
            elif "self signed" in msg.lower() or "unable to get local issuer" in msg.lower():
                inner = 'Custom { kind: InvalidData, error: InvalidCertificate(UnknownIssuer) }'
            elif "expired" in msg.lower():
                inner = 'Custom { kind: InvalidData, error: InvalidCertificate(Expired) }'
            else:
                inner = f'Custom {{ kind: InvalidData, error: {rust_str_debug(msg)} }}'
            raise _reqwest_request_error(
                url, f'hyper_util::client::legacy::Error(Connect, {inner})')
        except (ssl.SSLError, OSError) as e:
            raise _reqwest_request_error(url, _io_source(e) if isinstance(e, OSError) else
                                         f'hyper_util::client::legacy::Error(Connect, Custom {{ kind: InvalidData, error: {rust_str_debug(str(e))} }})')
        raw = sock
    host_header = host if (port in (80, 443)) else f"{host}:{port}"
    req = f"GET {path} HTTP/1.1\r\naccept: */*\r\nhost: {host_header}\r\n\r\n"
    raw.sendall(req.encode())
    return _read_response(url, raw, out_chunks)

def _read_response(url, sock, out_chunks):
    f = sock.makefile("rb")
    header = b""
    try:
        while b"\r\n\r\n" not in header and len(header) < 131072:
            chunk = f.read1(8192) if hasattr(f, "read1") else f.read(8192)
            if not chunk:
                break
            header += chunk
    except (ssl.SSLError, OSError) as e:
        raise _reqwest_request_error(url, _io_source(e) if isinstance(e, OSError) else str(e))
    if b"\r\n\r\n" not in header:
        raise _reqwest_request_error(
            url, 'hyper_util::client::legacy::Error(Io, Custom { kind: UnexpectedEof, error: "connection closed before message completed" })')
    head, rest = header.split(b"\r\n\r\n", 1)
    lines = head.split(b"\r\n")
    status_parts = lines[0].split(b" ", 2)
    if len(status_parts) < 2 or not status_parts[1].isdigit():
        raise _reqwest_request_error(url, 'hyper_util::client::legacy::Error(Io, Custom { kind: InvalidData, error: "invalid HTTP version" })')
    status = int(status_parts[1])
    reason = status_parts[2] if len(status_parts) > 2 else b""
    headers = {}
    for line in lines[1:]:
        if b":" in line:
            k, v = line.split(b":", 1)
            headers[k.strip().lower().decode("latin1")] = v.strip().decode("latin1")
    if status in (301, 302, 303, 307, 308) and "location" in headers:
        try:
            f.close(); sock.close()
        except Exception:
            pass
        return ("redirect", headers["location"], status, reason)
    if status >= 400:
        raise ReqwestError(
            f'reqwest::Error {{ kind: Status({status}, Some(ReasonPhrase({rust_bytes_debug(reason)}))), url: {rust_str_debug(url)} }}')
    total = None
    if "content-length" in headers:
        try:
            total = int(headers["content-length"])
        except Exception:
            total = None
    received = 0
    body = bytearray()
    def feed(chunk):
        nonlocal received
        if not chunk:
            return
        received += len(chunk)
        body.extend(chunk)
        out_chunks.append(chunk)
        if total:
            pct = (received * 100) // total if total else 100
            if pct > 100:
                pct = 100
            log_info("rustowl::toolchain", f"{pct:3d}% received")
    try:
        if headers.get("transfer-encoding", "").lower() == "chunked":
            buf = rest
            # small chunked decoder
            while True:
                while b"\r\n" not in buf:
                    more = f.read1(8192) if hasattr(f, "read1") else f.read(8192)
                    if not more:
                        raise OSError("eof in chunked body")
                    buf += more
                line, buf = buf.split(b"\r\n", 1)
                size = int(line.split(b";", 1)[0].strip() or b"0", 16)
                if size == 0:
                    break
                need = size
                while need > 0:
                    if buf:
                        take = buf[:need]; buf = buf[len(take):]; need -= len(take); feed(take)
                    else:
                        take = f.read1(min(8192, need)) if hasattr(f, "read1") else f.read(min(8192, need))
                        if not take:
                            raise OSError("eof in chunk")
                        need -= len(take); feed(take)
                # trailing CRLF
                while len(buf) < 2:
                    more = f.read1(8192) if hasattr(f, "read1") else f.read(8192)
                    if not more:
                        break
                    buf += more
                buf = buf[2:]
        elif total is not None:
            if rest:
                feed(rest[:total])
            while received < total:
                chunk = f.read1(16384) if hasattr(f, "read1") else f.read(16384)
                if not chunk:
                    break
                feed(chunk)
            if received < total:
                raise ReqwestError(
                    f'reqwest::Error {{ kind: Body, source: hyper::Error(Body, Custom {{ kind: UnexpectedEof, error: IncompleteBody }}) }}')
        else:
            if rest:
                feed(rest)
            while True:
                chunk = f.read1(16384) if hasattr(f, "read1") else f.read(16384)
                if not chunk:
                    break
                feed(chunk)
    except ReqwestError:
        raise
    except Exception as e:
        raise _reqwest_request_error(url, _io_source(e) if isinstance(e, OSError) else str(e))
    finally:
        try:
            f.close(); sock.close()
        except Exception:
            pass
    return ("ok", bytes(body), status, reason)

def http_download(url):
    current = url
    chunks = []
    for _i in range(11):
        result = _http_request_once(current, chunks)
        if result[0] == "ok":
            return result[1]
        # redirect
        loc = result[1]
        if loc.startswith("http://") or loc.startswith("https://"):
            current = loc
        else:
            parsed = _parse_url(current)
            scheme, host, port, _path = parsed
            authority = host + (f":{port}" if port and port not in (80, 443) else "")
            if loc.startswith("/"):
                current = f"{scheme}://{authority}{loc}"
            else:
                base = _path.rsplit("/", 1)[0] + "/"
                current = f"{scheme}://{authority}{base}{loc}"
        chunks = []
    raise ReqwestError(
        f'reqwest::Error {{ kind: Redirect, url: {rust_str_debug(url)}, source: TooManyRedirects }}')

def _unpack_targz(data, dest):
    dest = fs_str(dest)
    bio = io.BytesIO(data)
    # gzip decompression errors should surface here.
    with tarfile.open(fileobj=bio, mode="r:gz") as tf:
        members = tf.getmembers()
        for m in members:
            name = m.name
            # Rust tar unpack: strip leading '/', refuse '..'
            parts = []
            unsafe = False
            for part in name.split("/"):
                if part in ("", "."):
                    continue
                if part == "..":
                    unsafe = True
                    break
                parts.append(part)
            if unsafe or not parts:
                if unsafe:
                    raise tarfile.TarError("unsafe path")
                continue
            target = os.path.join(dest, *parts)
            if m.isdir():
                os.makedirs(target, exist_ok=True)
                try:
                    os.chmod(target, m.mode & 0o777 or 0o755)
                except Exception:
                    pass
            elif m.issym() or m.islnk():
                parent = os.path.dirname(target)
                if parent:
                    os.makedirs(parent, exist_ok=True)
                if os.path.lexists(target):
                    os.remove(target)
                try:
                    os.symlink(m.linkname, target)
                except Exception:
                    raise
            elif m.isfile():
                parent = os.path.dirname(target)
                if parent:
                    os.makedirs(parent, exist_ok=True)
                src = tf.extractfile(m)
                if src is None:
                    continue
                with open(target, "wb") as out:
                    shutil.copyfileobj(src, out)
                try:
                    os.chmod(target, m.mode & 0o777)
                except Exception:
                    pass
            # other entry types are ignored by our simple unpacker

def download_and_unpack(url, dest):
    log_info("rustowl::toolchain", f"start downloading {url}...")
    try:
        data = http_download(url)
    except ReqwestError as e:
        log_trace("reqwest::retry", "shouldn't retry!")
        log_error("rustowl::toolchain", "failed to download tarball")
        log_error("rustowl::toolchain", e.debug)
        return False
    except Exception as e:
        log_error("rustowl::toolchain", "failed to download tarball")
        log_error("rustowl::toolchain", str(e))
        return False
    log_info("rustowl::toolchain", "download finished")
    try:
        _unpack_targz(data, dest)
    except Exception:
        log_error("rustowl::toolchain", "failed to unpack tarball")
        return False
    log_info("rustowl::toolchain", "successfully unpacked")
    return True

def _make_tempdir():
    base = os.environ.get("TMPDIR")
    if not base:
        base = "/tmp"
    # tempfile::tempdir(): fails if the base does not exist / is not a dir.
    if not os.path.isdir(base):
        return None
    alphabet = string.ascii_letters + string.digits
    for _ in range(100):
        suffix = "".join(random.choice(alphabet) for _ in range(6))
        path = os.path.join(base, ".tmp" + suffix)
        try:
            os.mkdir(path, 0o755)
            return path
        except FileExistsError:
            continue
        except Exception:
            return None
    return None

def _copy_dir_recursive(src, dst):
    src = fs_str(src); dst = fs_str(dst)
    if not os.path.isdir(src):
        # walkdir over a missing root yields only an (ignored) error entry
        return True
    ok = True
    for root, dirs, files in os.walk(src):
        rel = os.path.relpath(root, src)
        target_root = dst if rel == "." else os.path.join(dst, rel)
        try:
            os.makedirs(target_root, exist_ok=True)
        except Exception:
            ok = False
        for name in files:
            s = os.path.join(root, name)
            d = os.path.join(target_root, name)
            try:
                shutil.copyfile(s, d)
                try:
                    shutil.copymode(s, d)
                except Exception:
                    pass
            except Exception:
                ok = False
        # symlinked directories appear in dirs; treat as files like fs::copy would
        for name in list(dirs):
            s = os.path.join(root, name)
            if os.path.islink(s):
                d = os.path.join(target_root, name)
                try:
                    shutil.copyfile(s, d)
                except Exception:
                    ok = False
                dirs.remove(name)
    return ok

def install_rust_toolchain(runtime_opt):
    runtime = fs_str(runtime_opt) if runtime_opt is not None else get_runtime_dir()
    if runtime is None:
        log_error("rustowl::toolchain", "failed to create toolchain directory")
        return False
    sysroot = path_join(runtime, "sysroot", TOOLCHAIN_NAME)
    try:
        os.makedirs(sysroot, exist_ok=True)
        if not os.path.isdir(sysroot):
            raise OSError("not a directory")
    except Exception:
        log_error("rustowl::toolchain", "failed to create toolchain directory")
        return False
    log_info("rustowl::toolchain", "start installing Rust toolchain...")
    for comp in ("rustc", "rust-std", "cargo"):
        tempdir = _make_tempdir()
        if tempdir is None:
            return False
        try:
            log_info("rustowl::toolchain", f"temp dir is made: {display_path(tempdir)}")
            top = f"{comp}-nightly-{TARGET_TRIPLE}"
            url = f"https://static.rust-lang.org/dist/{TOOLCHAIN_DATE}/{top}.tar.gz"
            if not download_and_unpack(url, tempdir):
                return False
            comp_list = os.path.join(tempdir, top, "components")
            try:
                with open(comp_list, "r", encoding="utf-8") as f:
                    content = f.read()
            except Exception:
                log_error("rustowl::toolchain", "failed to read components list")
                return False
            for line in content.splitlines():
                src = os.path.join(tempdir, top, line)
                _copy_dir_recursive(src, sysroot)
                log_info("rustowl::toolchain", f"component {line} successfully installed")
        finally:
            shutil.rmtree(tempdir, ignore_errors=True)
    log_info("rustowl::toolchain", "installing Rust toolchain finished")
    return True

def setup_toolchain(runtime_opt=None):
    if not install_rust_toolchain(runtime_opt):
        return False
    runtime = fs_str(runtime_opt) if runtime_opt is not None else get_runtime_dir()
    log_info("rustowl::toolchain", "start installing RustOwl toolchain...")
    url = (f"https://github.com/cordx56/rustowl/releases/download/{VERSION}/"
           f"rustowl-{TARGET_TRIPLE}.tar.gz")
    if runtime is not None and download_and_unpack(url, runtime):
        log_info("rustowl::toolchain", "installing RustOwl toolchain finished")
    else:
        if runtime is None:
