    # The url crate trims leading/trailing C0 controls and spaces, and strips
    # tabs/newlines anywhere in the input.
    s = raw.strip("".join(chr(i) for i in range(0x21)))
    s = s.replace("\t", "").replace("\n", "").replace("\r", "")
    m = re.match(r"^([A-Za-z][A-Za-z0-9+.\-]*):(.*)$", s, re.DOTALL)
    if not m:
        raise UrlParseError(f'relative URL without a base: "{raw}"')
    scheme = m.group(1).lower()
    rest = m.group(2)
    host = None
    path = rest
    if rest.startswith("//"):
        after = rest[2:]
        slash = after.find("/")
        qmark = after.find("?")
        cut = len(after)
        if slash != -1:
            cut = slash
        if qmark != -1:
            cut = min(cut, qmark)
        authority = after[:cut]
        path = after[cut:] if cut < len(after) and after[cut] == "/" else ""
        if "@" in authority:
            authority = authority.rsplit("@", 1)[1]
        host = authority
        if authority.startswith("["):
            end = authority.find("]")
            host = authority[1:end] if end != -1 else authority
            r = authority[end + 1:] if end != -1 else ""
            if r.startswith(":") and r[1:] and not r[1:].isdigit():
                raise UrlParseError(f'invalid port number: "{raw}"')
        elif ":" in authority:
            host, p = authority.rsplit(":", 1)
            if p and not p.isdigit():
                raise UrlParseError(f'invalid port number: "{raw}"')
        host = host.lower()
    # strip query/fragment for path purposes
    path = path.split("?", 1)[0].split("#", 1)[0]
    if scheme == "file":
        path = path.replace("\\", "/")
    # dot segment normalisation (url crate)
    if path:
        absolute = path.startswith("/")
        out = []
        for seg in path.split("/"):
            if seg == ".":
                continue
            if seg == "..":
                if out and out[-1] != "":
                    out.pop()
                continue
            out.append(seg)
        path = "/".join(out)
        if absolute and not path.startswith("/"):
            path = "/" + path
    return scheme, host, path

def url_to_file_path(raw):
    """Url::to_file_path on Unix; returns a filesystem str or None."""
    try:
        scheme, host, path = parse_url(raw)
    except UrlParseError:
        raise
    if scheme != "file":
        return None
    if host not in (None, "", "localhost"):
        return None
    if not path.startswith("/"):
        return None
    # Windows drive-letter paths are not valid Unix file paths in the url crate
    if re.match(r"^/[A-Za-z][:|](/|$)", path):
        return None
    raw_bytes = _percent_decode_bytes(path)
    return os.fsdecode(raw_bytes)

def uri_to_existing_file(raw):
    """Helper shared by cursor/did_open: to_file_path filtered by is_file."""
    p = url_to_file_path(raw)
    if p is None:
        return None
    if path_is_file(p):
        return p
    return None

# ---------------------------------------------------------------------------
# cargo metadata + workspaces

def _subprocess_env(extra):
    env = dict(os.environ)
    env.update(extra)
    return env

def toolchain_env(rustowlc_path, include_rustc=True, target_dir=None, cache_dir=None):
    sysroot = get_sysroot() or sysroot_candidate()
    env = {}
    old_ld = os.environ.get("LD_LIBRARY_PATH", "")
    env["LD_LIBRARY_PATH"] = f"{path_join(sysroot, 'lib')}:{old_ld}"
    env["CARGO_ENCODED_RUSTFLAGS"] = f"--sysroot={sysroot}"
    env["RUSTC_BOOTSTRAP"] = "1"
    if include_rustc:
        env["RUSTC"] = rustowlc_path
        env["RUSTC_WORKSPACE_WRAPPER"] = rustowlc_path
    if target_dir is not None:
        env["CARGO_TARGET_DIR"] = target_dir
    if cache_dir is not None:
        env["RUSTOWL_CACHE_DIR"] = cache_dir
    return env

def run_cargo_metadata(directory, cargo_path, rustowlc_path):
    """Return a metadata dict, or None on any failure (cargo_metadata-like)."""
    directory = fs_str(directory)
    if directory == "":
        return None
    env = _subprocess_env(toolchain_env(rustowlc_path))
    try:
        proc = subprocess.run(
            [cargo_path, "metadata", "--filter-platform", TARGET_TRIPLE],
            cwd=directory, stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    except Exception:
        return None
    if proc.returncode != 0:
        return None
    try:
        meta = json.loads(proc.stdout.decode("utf-8"))
    except Exception:
        return None
    if not isinstance(meta, dict):
        return None
    # Required fields in cargo_metadata::Metadata (subset we rely on).
    if not isinstance(meta.get("packages"), list):
        return None
    if not isinstance(meta.get("workspace_members"), list):
        return None
    if not isinstance(meta.get("workspace_root"), str):
        return None
    if not isinstance(meta.get("target_directory"), str):
        return None
    for pkg in meta["packages"]:
        if not isinstance(pkg, dict):
            return None
        if not isinstance(pkg.get("name"), str):
            return None
        if not isinstance(pkg.get("manifest_path"), str):
            return None
        if not isinstance(pkg.get("id"), str):
            return None
    return meta

class Workspace:
    def __init__(self, root, package=None, metadata=None):
        self.root = root                # workspace_root, or a file path
        self.package = package          # selected cargo_metadata package or None
        self.metadata = metadata        # full metadata dict or None

    @property
    def is_cargo(self):
        return self.package is not None

    @property
    def target_directory(self):
        if self.metadata:
            return self.metadata.get("target_directory")
        return None

    def dedup_key(self):
        return tuple(path_components(self.root))

def get_workspace(path):
    """Mirror of the reference get_workspace/Workspace::new behaviour."""
    ensure_toolchain_or_exit()
    path = fs_str(path)
    cargo_path = get_tool("cargo")
    rustowlc_path = get_tool("rustowlc")
    if path_is_file(path):
        parent = path_parent(path)
        directory = parent if parent is not None else path
    else:
        directory = path
    meta = run_cargo_metadata(directory, cargo_path, rustowlc_path)
    if meta is not None:
        root = meta["workspace_root"]
        # select the workspace package whose manifest dir contains the path
        try:
            cand = canonicalize(path)
        except Exception:
            cand = path
        members = set(m for m in meta.get("workspace_members", []) if isinstance(m, str))
        best = None
        best_len = -1
        for pkg in meta["packages"]:
            if pkg.get("id") not in members:
                continue
            manifest_dir = path_parent(pkg.get("manifest_path", "")) or ""
            if manifest_dir and path_starts_with(cand, manifest_dir):
                l = len(path_components(manifest_dir))
                if l > best_len:
                    best = pkg
                    best_len = l
        return Workspace(root=root, package=best, metadata=meta)
    # metadata failed: a single .rs file is still analysable on its own
    if path_is_file(path) and path_extension(path) == "rs":
        return Workspace(root=path, package=None, metadata=None)
    log_warn("rustowl::lsp::analyze", f"Invalid analysis target: {display_path(path)}")
    return None

def run_cargo_metadata_command():
    """`cargo metadata --format-version 1` as used by the clean command."""
    cargo = os.environ.get("CARGO") or "cargo"
    try:
        proc = subprocess.run([cargo, "metadata", "--format-version", "1"],
                              stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                              stderr=subprocess.PIPE)
    except Exception:
        return None
    if proc.returncode != 0:
        return None
    try:
        meta = json.loads(proc.stdout.decode("utf-8"))
    except Exception:
        return None
    if isinstance(meta, dict) and isinstance(meta.get("target_directory"), str):
        return meta
    return None

def clean_command():
    meta = run_cargo_metadata_command()
    if meta is not None:
        owl = path_join(meta["target_directory"], "owl")
        try:
            if os.path.islink(owl):
                os.unlink(owl)
            elif os.path.isdir(owl):
                shutil.rmtree(owl)
        except Exception:
            pass
    return 0

# ---------------------------------------------------------------------------
# analysis-data parsing (flexible: accept the shapes a rustowlc may emit)

def _as_range(obj):
    if not isinstance(obj, dict):
        return None
    def pos(p):
        if isinstance(p, dict) and isinstance(p.get("line"), int) and isinstance(p.get("character"), int):
            return {"line": p["line"], "character": p["character"]}
        return None
    s = pos(obj.get("start")); e = pos(obj.get("end"))
    if s is None or e is None:
        return None
    return {"start": s, "end": e}

def _normalize_decoration(obj):
    if not isinstance(obj, dict):
        return None
    rng = _as_range(obj.get("range")) if "range" in obj else _as_range(obj)
    if rng is None:
        # span-style objects: {start:{...}, end:{...}}
        rng = _as_range(obj.get("span")) if isinstance(obj.get("span"), dict) else None
    if rng is None:
        return None
    deco = {"range": rng}
    for key in ("type", "kind", "deco_type", "decoration_type"):
        if isinstance(obj.get(key), str):
            deco["type"] = obj[key]
            break
    for key in ("hover_text", "hoverText", "message", "text", "label"):
        if isinstance(obj.get(key), str):
            deco["hover_text"] = obj[key]
            break
    return deco

def _extract_decorations(value, out_groups, group_hint=None):
    """Collect (filename, [decorations]) pairs from a decoded JSON value."""
    found = []
    if isinstance(value, list):
        decos = [d for d in (_normalize_decoration(v) for v in value) if d]
        if decos:
            found.append((group_hint, decos))
        for v in value:
            if isinstance(v, (dict, list)):
                found.extend(_extract_decorations(v, out_groups, group_hint))
        return found
    if isinstance(value, dict):
        filename = None
        for key in ("filename", "file", "path", "file_name", "src_path"):
            if isinstance(value.get(key), str):
                filename = value[key]
                break
        for key in ("decorations", "decos", "items", "functions", "locals", "results"):
            v = value.get(key)
            if isinstance(v, list):
                decos = [d for d in (_normalize_decoration(x) for x in v) if d]
                if decos:
                    found.append((filename or group_hint, decos))
                else:
                    for x in v:
                        found.extend(_extract_decorations(x, out_groups, filename or group_hint))
        single = _normalize_decoration(value)
        if single:
            found.append((filename or group_hint, [single]))
        # filename -> decorations mapping form
        for k, v in value.items():
            if isinstance(v, list) and k not in ("decorations", "decos"):
                decos = [d for d in (_normalize_decoration(x) for x in v) if d]
                if decos:
                    found.append((k, decos))
    return found

