class ProgressHandle:
    def __init__(self, server, token):
        self.server = server
        self.token = token
        self.finished = False

    def begin(self):
        self.server.send_notification("$/progress", {
            "token": self.token,
            "value": {"kind": "begin", "title": "RustOwl", "cancellable": False, "percentage": 0},
        })

    def report(self, message, percentage):
        self.server.send_notification("$/progress", {
            "token": self.token,
            "value": {"kind": "report", "cancellable": False, "message": message,
                      "percentage": int(percentage)},
        })

    def finish(self):
        if not self.finished:
            self.finished = True
            self.server.send_notification("$/progress", {
                "token": self.token, "value": {"kind": "end"},
            })

class Backend:
    def __init__(self, context="lsp", all_targets=False, all_features=False):
        self.context = context
        self.all_targets = all_targets
        self.all_features = all_features
        self.workspaces = []
        self._ws_lock = threading.Lock()
        self.status = "error"
        self.analyzed = {}          # canonical path -> [decorations]
        self.analyzed_groups = {}   # canonical path -> [[decorations], ...]
        self._data_lock = threading.Lock()
        self.processes = []         # list[subprocess.Popen]
        self._proc_lock = threading.Lock()
        self.server = None          # LSPServer, for progress
        self.progress_supported = False

    # -- workspaces --
    def add_workspace(self, ws):
        if ws is None:
            return
        with self._ws_lock:
            for existing in self.workspaces:
                if existing.dedup_key() == ws.dedup_key():
                    return
            self.workspaces.append(ws)

    def add_path(self, path):
        ws = get_workspace(path)
        if ws is not None:
            self.add_workspace(ws)
            return True
        return False

    # -- analysis --
    def analyze_async(self):
        th = threading.Thread(target=self._analyze_guarded, daemon=True)
        th.start()
        return th

    def _analyze_guarded(self):
        try:
            self.analyze_blocking()
        except Exception:
            pass

    def analyze_blocking(self):
        log_info("rustowl::lsp::backend", "wait 100ms for rust-analyzer")
        time.sleep(0.1)
        log_info("rustowl::lsp::backend", "stop running analysis processes")
        with self._proc_lock:
            procs = self.processes
            self.processes = []
        for p in procs:
            try:
                if p.poll() is None:
                    p.kill()
            except Exception:
                pass
        log_info("rustowl::lsp::backend", "start analysis")
        with self._ws_lock:
            workspaces = list(self.workspaces)
        log_info("rustowl::lsp::backend", f"analyze {len(workspaces)} packages...")
        if workspaces:
            self.status = "analyzing"
        threads = []
        for ws in workspaces:
            th = threading.Thread(target=self._run_workspace_guarded, args=(ws,), daemon=True)
            th.start()
            threads.append(th)
        for th in threads:
            th.join()
        with self._data_lock:
            success = bool(self.analyzed)
        self.status = "analyzed" if success else "error"
        return success

    def _run_workspace_guarded(self, ws):
        try:
            self._run_workspace(ws)
        except Exception:
            pass

    def _make_progress(self):
        if not (self.progress_supported and self.server is not None):
            return None
        token = str(uuid.uuid4())
        handle = ProgressHandle(self.server, token)
        # window/workDoneProgress/create is awaited, errors are ignored.
        try:
            self.server.send_request("window/workDoneProgress/create", {"token": token})
        except Exception:
            pass
        handle.begin()
        return handle

    def _register_process(self, proc):
        with self._proc_lock:
            self.processes.append(proc)

    def _panic_location(self):
        if self.context == "lsp":
            return "src/lsp/analyze.rs:222:41"
        return "/workspace/src/lsp/analyze.rs:222:41"

    def _run_workspace(self, ws):
        if ws.is_cargo:
            self._run_cargo(ws)
        else:
            self._run_file(ws)

    def _run_cargo(self, ws):
        meta = ws.metadata
        package = ws.package
        name = package.get("name", "")
        target_dir = path_join(meta.get("target_directory", ""), "owl")
        cache_dir = path_join(target_dir, "cache")
        workspace_root = meta.get("workspace_root", "")
        log_info("rustowl::lsp::analyze", "clear cargo cache")
        cargo_path = get_tool("cargo")
        rustowlc_path = get_tool("rustowlc")
        try:
            subprocess.run(
                [cargo_path, "clean", "--package", name],
                cwd=workspace_root or None, stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                env=_subprocess_env(toolchain_env(rustowlc_path, target_dir=target_dir)))
        except Exception:
            pass
        cargo_path = get_tool("cargo")
        rustowlc_path = get_tool("rustowlc")
        log_info("rustowl::lsp::analyze", f"start analyzing package {name}")
        progress = self._make_progress()
        try:
            args = [cargo_path, "check", "--workspace"]
            if self.all_targets:
                args.append("--all-targets")
            if self.all_features:
                args.append("--all-features")
            args += ["--keep-going", "--message-format=json"]
            try:
                proc = subprocess.Popen(
                    args, cwd=workspace_root or None, stdout=subprocess.PIPE,
                    env=_subprocess_env(toolchain_env(
                        rustowlc_path, target_dir=target_dir, cache_dir=cache_dir)))
            except OSError as e:
                rust_panic("tokio-runtime-worker", self._panic_location(),
                           f"called `Result::unwrap()` on an `Err` value: {os_error_debug(e)}")
                return
            self._register_process(proc)
            total_packages = len(meta.get("packages", []) or []) or 1
            checked_ids = set()
            self._read_process_stdout(proc, mode="cargo", workspace=ws,
                                      progress=progress, total_packages=total_packages,
                                      checked_ids=checked_ids)
        finally:
            if progress is not None:
                progress.finish()

    def _run_file(self, ws):
        rustowlc_path = get_tool("rustowlc")
        filename = ws.root
        log_info("rustowl::lsp::analyze", f"start analyzing {display_path(filename)}")
        progress = self._make_progress()
        try:
            sysroot = get_sysroot() or sysroot_candidate()
            args = [rustowlc_path, rustowlc_path, f"--sysroot={sysroot}",
                    "--crate-type=lib", "-o/dev/null", filename]
            try:
                proc = subprocess.Popen(
                    args, stdout=subprocess.PIPE,
                    env=_subprocess_env(toolchain_env(rustowlc_path, include_rustc=False)))
            except OSError as e:
                rust_panic("tokio-runtime-worker", self._panic_location(),
                           f"called `Result::unwrap()` on an `Err` value: {os_error_debug(e)}")
                return
            self._register_process(proc)
            self._read_process_stdout(proc, mode="file", workspace=ws, progress=progress)
        finally:
            if progress is not None:
                progress.finish()

    def _read_process_stdout(self, proc, mode, workspace, progress=None,
                             total_packages=1, checked_ids=None):
        if checked_ids is None:
            checked_ids = set()
        try:
            stream = proc.stdout
            if stream is not None:
                while True:
                    raw = stream.readline()
                    if not raw:
                        break
                    try:
                        line = raw.decode("utf-8")
                    except UnicodeDecodeError:
                        break
                    line = line.rstrip("\r\n")
                    if mode == "cargo":
                        self._handle_cargo_line(line, workspace, progress,
                                                total_packages, checked_ids)
                    else:
                        self._handle_data_line(line, workspace)
        except Exception:
            pass
        log_info("rustowl::lsp::analyze", "stdout closed")
        try:
            if proc.poll() is None:
                proc.kill()
        except Exception:
            pass
        try:
            proc.wait(timeout=2)
        except Exception:
            pass

    def _handle_cargo_line(self, line, workspace, progress, total_packages, checked_ids):
        line = line.strip()
        if not line:
            return
        handled_artifact = False
        try:
            value = json.loads(line)
        except Exception:
            value = None
        if isinstance(value, dict) and value.get("reason") == "compiler-artifact":
            target = value.get("target") if isinstance(value.get("target"), dict) else {}
            tname = target.get("name") if isinstance(target, dict) else None
            if isinstance(tname, str):
                handled_artifact = True
                log_info("rustowl::lsp::analyze", f"crate {tname} checked")
                pid = value.get("package_id") or tname
                checked_ids.add(str(pid))
                if progress is not None:
                    pct = int(len(checked_ids) * 100 / total_packages) if total_packages else 100
                    if pct > 100:
                        pct = 100
                    progress.report(f"{tname} analyzed", pct)
                # a real rustowlc may have dropped analysis data in the cache dir
                self._scan_cache_dir(workspace)
        if not handled_artifact:
            self._handle_data_line(line, workspace)

    def _handle_data_line(self, line, workspace):
        line = line.strip()
        if not line:
            return
        try:
            value = json.loads(line)
        except Exception:
            return
        if isinstance(value, dict) and value.get("reason"):
            return  # cargo protocol message, not analysis data
        pairs = _extract_decorations(value, [])
        for filename, decos in pairs:
            self._store_decorations(filename, decos, workspace)

    def _scan_cache_dir(self, workspace):
        if workspace is None or not workspace.is_cargo:
            return
        cache_dir = path_join(workspace.target_directory or "", "owl", "cache")
        if not path_is_dir(cache_dir):
            return
        for root, _dirs, files in os.walk(cache_dir):
            for name in files:
                if not name.endswith(".json"):
                    continue
                p = os.path.join(root, name)
                try:
                    with open(p, "rb") as f:
                        value = json.loads(f.read().decode("utf-8"))
                except Exception:
                    continue
                stem = name[:-5]
                for filename, decos in _extract_decorations(value, []):
                    self._store_decorations(filename or stem, decos, workspace)

    def _store_decorations(self, filename, decos, workspace):
        if not decos:
            return
        key = None
        if isinstance(filename, str) and filename:
            cand = filename
            if not os.path.isabs(cand) and workspace is not None:
                cand = os.path.join(workspace.root, cand)
            try:
                key = canonicalize(cand)
            except Exception:
                key = cand
        elif workspace is not None and not workspace.is_cargo:
            try:
                key = canonicalize(workspace.root)
            except Exception:
                key = workspace.root
        if key is None:
            return
        with self._data_lock:
            self.analyzed_groups.setdefault(key, []).append(decos)
            flat = self.analyzed.setdefault(key, [])
            flat.extend(decos)

    # -- cursor --
    def cursor(self, uri, position):
        # may raise UrlParseError (handled as invalid params by caller)
        path = uri_to_existing_file(uri)
        status = self.status
        decorations = []
        is_analyzed = False
        path_out = None
        if path is not None:
            # camino conversion in the reference
            try:
                path_out = os.fsencode(path).decode("utf-8")
            except UnicodeDecodeError:
                return ("internal_error", "path contains invalid UTF-8 characters")
            key = None
            try:
                key = canonicalize(path)
            except Exception:
                key = path
            with self._data_lock:
                groups = list(self.analyzed_groups.get(key, []))
                flat = list(self.analyzed.get(key, []))
            if flat:
                is_analyzed = True
                decorations = self._select_decorations(groups, flat, position)
        return {
            "decorations": decorations,
            "is_analyzed": is_analyzed,
            "path": path_out,
            "status": status,
        }

    def _select_decorations(self, groups, flat, position):
        line = position.get("line", 0)
        char = position.get("character", 0)
        def contains(d):
            r = d.get("range") or {}
            s = r.get("start") or {}; e = r.get("end") or {}
            sp = (s.get("line", 0), s.get("character", 0))
            ep = (e.get("line", 0), e.get("character", 0))
            return sp <= (line, char) < ep or sp <= (line, char) <= ep
        for group in groups:
            if any(contains(d) for d in group):
                return group
        return flat

