            rendered = json.dumps(json_plain(params), ensure_ascii=False, separators=(",", ":"))
            self.send_error(rid, -32602, f"Unexpected params: {rendered}")
            return
        self.send_response(rid, None)

    def _do_known_request(self, method, rid, params, params_present):
        struct_name, fields = KNOWN_REQUESTS[method]
        try:
            if not params_present:
                raise SerdeError("Missing params field")
            deserialize_struct(params, struct_name, fields)
        except SerdeError as e:
            self.send_error(rid, -32602, str(e))
            return
        self.send_error(rid, -32601, "Method not found")

    def _do_custom(self, method, rid, params, params_present):
        try:
            if not params_present:
                raise SerdeError("Missing params field")
            if method == "rustowl/analyze":
                deserialize_struct(params, "AnalyzeRequest", [])
                log_info("rustowl::lsp::backend", "rustowl/analyze request received")
                self.backend.analyze_async()
                self.send_response(rid, {})
                return
            # rustowl/cursor
            parsed = deserialize_struct(params, "CursorRequest", [
                ("position", True, val_position),
                ("document", True, val_text_document_identifier),
            ])
        except SerdeError as e:
            self.send_error(rid, -32602, str(e))
            return
        uri = parsed["document"]["uri"]
        result = self.backend.cursor(uri, parsed["position"])
        if isinstance(result, tuple) and result and result[0] == "internal_error":
            self.send_error(rid, -32603, result[1])
            return
        self.send_response(rid, result)

    def _handle_notification(self, method, params):
        try:
            if method == "textDocument/didOpen":
                plain = json_plain(params) if params is not None else {}
                doc = plain.get("textDocument") if isinstance(plain, dict) else None
                uri = doc.get("uri") if isinstance(doc, dict) else None
                if isinstance(uri, str):
                    try:
                        path = uri_to_existing_file(uri)
                    except UrlParseError:
                        path = None
                    if path is not None:
                        ws = get_workspace(path)
                        if ws is not None:
                            self.backend.add_workspace(ws)
                            self.backend.analyze_async()
            elif method == "workspace/didChangeWorkspaceFolders":
                plain = json_plain(params) if params is not None else {}
                event = plain.get("event") if isinstance(plain, dict) else None
                added = event.get("added") if isinstance(event, dict) else None
                added_any = False
                if isinstance(added, list):
                    for folder in added:
                        if isinstance(folder, dict) and isinstance(folder.get("uri"), str):
                            try:
                                p = url_to_file_path(folder["uri"])
                            except UrlParseError:
                                p = None
                            if p is not None:
                                ws = get_workspace(p)
                                if ws is not None:
                                    self.backend.add_workspace(ws)
                                    added_any = True
                if added_any:
                    self.backend.analyze_async()
        except Exception:
            pass

