# ---------------------------------------------------------------------------
# serde-like validation helpers

class JObject:
    __slots__ = ("pairs",)
    def __init__(self, pairs):
        self.pairs = pairs
    def to_plain(self):
        out = {}
        for k, v in self.pairs:
            out[k] = json_plain(v)
        return out
    def get(self, key, default=None):
        result = default
        for k, v in self.pairs:
            if k == key:
                result = v
        return result
    def has(self, key):
        return any(k == key for k, _ in self.pairs)
    def keys(self):
        return [k for k, _ in self.pairs]

def json_plain(v):
    if isinstance(v, JObject):
        return v.to_plain()
    if isinstance(v, list):
        return [json_plain(x) for x in v]
    return v

class SerdeError(Exception):
    pass

def _unexpected(v):
    if isinstance(v, bool):
        return f"boolean `{str(v).lower()}`"
    if isinstance(v, str):
        return f"string {rust_str_debug(v)}"
    if isinstance(v, int):
        return f"integer `{v}`"
    if isinstance(v, float):
        s = repr(v)
        return f"floating point `{s}`"
    if v is None:
        return "null"
    if isinstance(v, list):
        return "sequence"
    if isinstance(v, (dict, JObject)):
        return "map"
    return str(v)

def _invalid_type(v, expected):
    raise SerdeError(f"invalid type: {_unexpected(v)}, expected {expected}")

def _sorted_pairs(value):
    if isinstance(value, JObject):
        # serde_json::Value uses a BTree map: last duplicate wins, sorted keys
        plain = {}
        for k, v in value.pairs:
            plain[k] = v
        return [(k, plain[k]) for k in sorted(plain.keys())]
    if isinstance(value, dict):
        return [(k, value[k]) for k in sorted(value.keys())]
    return None

def val_u32(v):
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        _invalid_type(v, "u32")
    if isinstance(v, float):
        _invalid_type(v, "u32")
    if v < 0 or v > 4294967295:
        raise SerdeError(f"invalid value: integer `{v}`, expected u32")
    return v

def val_i32(v):
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        _invalid_type(v, "i32")
    if isinstance(v, float):
        _invalid_type(v, "i32")
    if v < -2147483648 or v > 2147483647:
        raise SerdeError(f"invalid value: integer `{v}`, expected i32")
    return v

def val_string(v):
    if not isinstance(v, str):
        _invalid_type(v, "a string")
    return v

def val_bool(v):
    if not isinstance(v, bool):
        _invalid_type(v, "a boolean")
    return v

def val_url(v):
    if not isinstance(v, str):
        _invalid_type(v, "a string representing an URL")
    try:
        parse_url(v)
    except UrlParseError as e:
        raise SerdeError(str(e))
    return v

def val_any(v):
    return json_plain(v)

def deserialize_struct(value, struct_name, fields):
    """
    fields: list of (name, required, validator).
    Mirrors serde derive over a serde_json::Value (sorted map keys).
    """
    field_map = {f[0]: f for f in fields}
    result = {}
    pairs = _sorted_pairs(value)
    if pairs is not None:
        seen = set()
        for key, v in pairs:
            if key in field_map:
                name, _req, validator = field_map[key]
                result[name] = validator(v) if validator else json_plain(v)
                seen.add(name)
        for name, required, _validator in fields:
            if required and name not in seen:
                raise SerdeError(f"missing field `{name}`")
        return result
    if isinstance(value, list):
        if len(value) > len(fields):
            raise SerdeError(f"invalid length {len(value)}, expected fewer elements in array")
        for (name, _req, validator), v in zip(fields, value):
            result[name] = validator(v) if validator else json_plain(v)
        # serde requires every non-default field; approximate with all fields
        required_count = sum(1 for f in fields if f[1])
        if len(value) < required_count:
            raise SerdeError(
                f"invalid length {len(value)}, expected struct {struct_name} with {len(fields)} elements")
        return result
    _invalid_type(value, f"struct {struct_name}")

def val_position(v):
    return deserialize_struct(v, "Position", [
        ("line", True, val_u32), ("character", True, val_u32)])

def val_text_document_identifier(v):
    return deserialize_struct(v, "TextDocumentIdentifier", [("uri", True, val_url)])

def val_range(v):
    return deserialize_struct(v, "Range", [
        ("start", True, val_position), ("end", True, val_position)])

def _opt(validator):
    def check(v):
        if v is None:
            return None
        return validator(v)
    return check

def _seq_of(validator):
    def check(v):
        if not isinstance(v, list):
            _invalid_type(v, "a sequence")
        return [validator(x) for x in v]
    return check

