class PendingServerRequest:
    __slots__ = ("event", "result", "error")
    def __init__(self):
        self.event = threading.Event()
        self.result = None
        self.error = None

def _sorted_json_value(v):
    if isinstance(v, dict):
        return {k: _sorted_json_value(v[k]) for k in sorted(v.keys())}
    if isinstance(v, list):
        return [_sorted_json_value(x) for x in v]
    if isinstance(v, JObject):
        return _sorted_json_value(json_plain(v))
    return v

def _dumps(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"),
                        sort_keys=False).encode("utf-8", "surrogateescape")

class LSPServer:
    def __init__(self, backend):
        self.backend = backend
        backend.server = self
        self.state = "uninitialized"   # uninitialized|initializing|ready|shutdown|exited
        self._state_lock = threading.Lock()
        self._write_lock = threading.Lock()
        self._next_server_id = 0
        self._pending_server = {}
        self._pending_client = {}      # id-key -> True (in-flight client requests)
        self._cancelled = set()
        self._executor = ThreadPoolExecutor(max_workers=4)
        self._init_generation = 0
        self._stopped = False

    # ---------- outgoing ----------
    def _write_frame(self, body_bytes):
        frame = b"Content-Length: " + str(len(body_bytes)).encode() + b"\r\n\r\n" + body_bytes
        with self._write_lock:
            try:
                sys.stdout.buffer.write(frame)
                sys.stdout.buffer.flush()
            except Exception:
                pass

    def _id_key(self, rid):
        if isinstance(rid, bool):
            return ("bool", rid)
        if isinstance(rid, int):
            return ("num", rid)
        if isinstance(rid, str):
            return ("str", rid)
        return ("null", None)

    def send_response(self, rid, result):
        key = self._id_key(rid)
        with self._state_lock:
            if key in self._cancelled:
                self._cancelled.discard(key)
                self._pending_client.pop(key, None)
                return
            self._pending_client.pop(key, None)
        body = (b'{"jsonrpc":"2.0","result":' + _dumps(_sorted_json_value(result)) +
                b',"id":' + _dumps(rid) + b'}')
        self._write_frame(body)

    def send_error(self, rid, code, message, data=None, _has_data=False):
        key = self._id_key(rid)
        with self._state_lock:
            if key in self._cancelled:
                self._cancelled.discard(key)
                self._pending_client.pop(key, None)
                return
            self._pending_client.pop(key, None)
        err = b'{"code":' + _dumps(code) + b',"message":' + _dumps(message)
        if _has_data:
            err += b',"data":' + _dumps(_sorted_json_value(data))
        err += b'}'
        body = b'{"jsonrpc":"2.0","error":' + err + b',"id":' + _dumps(rid) + b'}'
        self._write_frame(body)

    def send_notification(self, method, params):
        body = (b'{"jsonrpc":"2.0","method":' + _dumps(method) +
                b',"params":' + _dumps(_sorted_json_value(params)) + b'}')
        self._write_frame(body)

    def send_request(self, method, params):
        with self._state_lock:
            rid = self._next_server_id
            self._next_server_id += 1
            pending = PendingServerRequest()
            self._pending_server[self._id_key(rid)] = pending
        body = (b'{"jsonrpc":"2.0","method":' + _dumps(method) +
                b',"params":' + _dumps(_sorted_json_value(params)) +
                b',"id":' + _dumps(rid) + b'}')
        self._write_frame(body)
        pending.event.wait()
        if pending.error is not None:
            raise RuntimeError(str(pending.error))
        return pending.result

    # ---------- framing ----------
    def serve(self):
        eprint_raw(f"RustOwl {VERSION}\nThis is an LSP server. You can use --help flag to show help.\n")
        stdin = sys.stdin.buffer
        buf = b""
        headers = []
        content_length = None
        in_headers = True
        exited_drain = False
        while True:
            chunk = os.read(0, 65536)
            if not chunk:
                break
            if exited_drain:
                continue
            buf += chunk
            # process all complete frames in buf
            while True:
                if in_headers:
                    idx = buf.find(b"\n")
                    if idx == -1:
                        break
                    line = buf[:idx].rstrip(b"\r")
                    buf = buf[idx + 1:]
                    if line == b"":
                        if content_length is None:
                            self._fatal_error(-32700, "Parse error")
                            return 0
                        in_headers = False
                        continue
                    if b":" not in line:
                        self._fatal_error(-32700, "Parse error")
                        return 0
                    name, value = line.split(b":", 1)
                    if name == b"Content-Length":
                        value = value.strip()
                        try:
                            if not value.isdigit():
                                raise ValueError
                            content_length = int(value)
                        except Exception:
                            self._fatal_error(-32700, "Parse error")
                            return 0
                    headers.append(line)
                else:
                    if len(buf) < content_length:
                        break
                    body = buf[:content_length]
                    buf = buf[content_length:]
                    in_headers = True
                    content_length = None
                    result = self._handle_body(body)
                    if result == "fatal":
                        return 0
                    if result == "exited":
                        exited_drain = True
                        buf = b""
                        break
        self._shutdown_processes()
        return 0

    def _fatal_error(self, code, message):
        err = b'{"code":' + _dumps(code) + b',"message":' + _dumps(message) + b'}'
        body = b'{"jsonrpc":"2.0","error":' + err + b',"id":null}'
        self._write_frame(body)

    def _shutdown_processes(self):
        with self.backend._proc_lock:
            procs = list(self.backend.processes)
            self.backend.processes = []
        for p in procs:
            try:
                if p.poll() is None:
                    p.kill()
            except Exception:
                pass

    # ---------- message handling ----------
    def _handle_body(self, body):
        try:
            text = body.decode("utf-8")
        except Exception:
            self._fatal_error(-32700, "Parse error")
            return "fatal"
        try:
            value = json.loads(text, object_pairs_hook=JObject)
        except Exception:
            self._fatal_error(-32700, "Parse error")
            return "fatal"
        if not isinstance(value, JObject):
            self._fatal_error(-32600, "Invalid request")
            return "fatal"
        jsonrpc = value.get("jsonrpc")
        method = value.get("method")
        has_id = value.has("id")
        rid = value.get("id") if has_id else None
        if jsonrpc != "2.0":
            self._fatal_error(-32600, "Invalid request")
            return "fatal"
        if has_id and not (rid is None or isinstance(rid, str) or
                           (isinstance(rid, int) and not isinstance(rid, bool))):
            self._fatal_error(-32600, "Invalid request")
            return "fatal"
        if method is None:
            # a response to one of our requests
            if has_id and (value.has("result") or value.has("error")):
                key = self._id_key(rid)
                with self._state_lock:
                    pending = self._pending_server.pop(key, None)
                if pending is not None:
                    if value.has("error"):
                        pending.error = value.get("error")
                    else:
                        pending.result = json_plain(value.get("result"))
                    pending.event.set()
                return None
            self._fatal_error(-32600, "Invalid request")
            return "fatal"
        if not isinstance(method, str):
            self._fatal_error(-32600, "Invalid request")
            return "fatal"
        params_present = value.has("params")
        params = value.get("params") if params_present else None
        return self._dispatch(method, rid if has_id else None, has_id, params, params_present)

    def _dispatch(self, method, rid, is_request, params, params_present):
        # exit is intercepted whatever it looks like
        if method == "exit":
            with self._state_lock:
                self.state = "exited"
            return "exited"
        with self._state_lock:
            state = self.state
        if state == "exited":
            return "exited"
        if method == "$/cancelRequest":
            if is_request:
                self.send_error(rid, -32600, "Invalid request")
                return None
            # notification: cancel an in-flight client request
            cancel_id = None
            if isinstance(params, (JObject, dict)):
                cancel_id = params.get("id")
            if cancel_id is not None:
                key = self._id_key(cancel_id)
                send_cancel = False
                with self._state_lock:
                    if key in self._pending_client:
                        self._cancelled.add(key)
                        self._pending_client.pop(key, None)
                        send_cancel = True
                        if self.state == "initializing":
                            self.state = "uninitialized"
                            self._init_generation += 1
                if send_cancel:
                    err = b'{"code":-32800,"message":"Canceled"}'
                    body = b'{"jsonrpc":"2.0","error":' + err + b',"id":' + _dumps(cancel_id) + b'}'
                    self._write_frame(body)
            return None
        if method.startswith("$/"):
            return None
        if method == "shutdown" and not is_request:
            with self._state_lock:
                if self.state == "ready":
                    self.state = "shutdown"
            return None
        known_notification = method in KNOWN_NOTIFICATIONS
        known_request = method in KNOWN_REQUESTS or method in (
            "rustowl/cursor", "rustowl/analyze", "initialize", "shutdown")
        if not known_notification and not known_request:
            if is_request:
                self.send_error(rid, -32601, "Method not found", method, _has_data=True)
            return None
        if known_notification and not known_request:
            if is_request:
                self.send_error(rid, -32600, "Invalid request")
                return None
            if state != "ready":
                return None
            self._executor.submit(self._handle_notification, method, params)
            return None
        # request methods from here on
        if not is_request:
            return None
        if method == "initialize":
            with self._state_lock:
                if self.state != "uninitialized":
                    self.send_error(rid, -32600, "Invalid request")
                    return None
                self.state = "initializing"
                self._init_generation += 1
                generation = self._init_generation
                self._pending_client[self._id_key(rid)] = True
            self._executor.submit(self._do_initialize, rid, params, params_present, generation)
            return None
        if state in ("uninitialized", "initializing"):
            self.send_error(rid, -32002, "Server not initialized")
            return None
        if state == "shutdown":
            self.send_error(rid, -32600, "Invalid request")
            return None
        if method == "shutdown":
            with self._state_lock:
                self.state = "shutdown"
                self._pending_client[self._id_key(rid)] = True
            self._executor.submit(self._do_shutdown, rid, params, params_present)
            return None
        with self._state_lock:
            self._pending_client[self._id_key(rid)] = True
        if method in ("rustowl/cursor", "rustowl/analyze"):
            self._executor.submit(self._do_custom, method, rid, params, params_present)
        else:
            self._executor.submit(self._do_known_request, method, rid, params, params_present)
        return None

    # ---------- handlers ----------
    def _do_initialize(self, rid, params, params_present, generation):
        try:
            if not params_present:
                raise SerdeError("Missing params field")
            parsed = self._parse_initialize(params)
        except SerdeError as e:
            with self._state_lock:
                if self._init_generation == generation and self.state == "initializing":
                    self.state = "uninitialized"
            self.send_error(rid, -32602, str(e))
            return
        # client capabilities -> progress support
        caps = parsed.get("capabilities") or {}
        try:
