    def serve(self):
        eprint_raw(f"RustOwl {VERSION}\nThis is an LSP server. You can use --help flag to show help.\n")
        stdin = sys.stdin.buffer
        buf = b""
        headers = []
        content_length = None
        in_headers = True
        exited_drain = False
        while True:
            chunk = os.read(0, 65536)
            if not chunk:
                break
            if exited_drain:
                continue
            buf += chunk
            # process all complete frames in buf
            while True:
                if in_headers:
                    idx = buf.find(b"\n")
                    if idx == -1:
                        break
                    line = buf[:idx].rstrip(b"\r")
                    buf = buf[idx + 1:]
                    if line == b"":
                        if content_length is None:
                            self._fatal_error(-32700, "Parse error")
                            return 0
                        in_headers = False
                        continue
                    if b":" not in line:
                        self._fatal_error(-32700, "Parse error")
                        return 0
                    name, value = line.split(b":", 1)
                    if name == b"Content-Length":
                        value = value.strip()
                        try:
                            if not value.isdigit():
                                raise ValueError
                            content_length = int(value)
                        except Exception:
                            self._fatal_error(-32700, "Parse error")
                            return 0
                    headers.append(line)
                else:
                    if len(buf) < content_length:
                        break
                    body = buf[:content_length]
                    buf = buf[content_length:]
