        params = value.get("params") if params_present else None
        return self._dispatch(method, rid if has_id else None, has_id, params, params_present)

    def _dispatch(self, method, rid, is_request, params, params_present):
        # exit is intercepted whatever it looks like
        if method == "exit":
            with self._state_lock:
