        def client_info(v):
            return deserialize_struct(v, "ClientInfo", [
                ("name", True, val_string), ("version", False, _opt(val_string))])
        def workspace_folder(v):
            return deserialize_struct(v, "WorkspaceFolder", [
                ("uri", True, val_url), ("name", True, val_string)])
        def trace_value(v):
            if isinstance(v, (JObject, dict)):
                return json_plain(v)
            if not isinstance(v, str):
                _invalid_type(v, "string or map")
