            return json_plain(v)
        fields = [
            ("capabilities", True, client_caps),
            ("clientInfo", False, _opt(client_info)),
            ("initializationOptions", False, _opt(val_any)),
            ("locale", False, _opt(val_string)),
            ("processId", False, _opt(val_u32)),
            ("rootPath", False, _opt(_opt(val_string))),
            ("rootUri", False, _opt(val_url)),
            ("trace", False, _opt(trace_value)),
            ("workDoneToken", False, _opt(val_any)),
            ("workspaceFolders", False, _opt(_opt(_seq_of(workspace_folder)))),
