        struct_name, fields = KNOWN_REQUESTS[method]
        try:
            if not params_present:
                raise SerdeError("Missing params field")
            deserialize_struct(params, struct_name, fields)
        except SerdeError as e:
            self.send_error(rid, -32602, str(e))
            return
