        result = self.backend.cursor(uri, parsed["position"])
        if isinstance(result, tuple) and result and result[0] == "internal_error":
            self.send_error(rid, -32603, result[1])
            return
        self.send_response(rid, result)

    def _handle_notification(self, method, params):
        try:
            if method == "textDocument/didOpen":
                plain = json_plain(params) if params is not None else {}
                doc = plain.get("textDocument") if isinstance(plain, dict) else None
                uri = doc.get("uri") if isinstance(doc, dict) else None
                if isinstance(uri, str):
                    try:
                        path = uri_to_existing_file(uri)
                    except UrlParseError:
