                plain = json_plain(params) if params is not None else {}
                event = plain.get("event") if isinstance(plain, dict) else None
                added = event.get("added") if isinstance(event, dict) else None
                added_any = False
                if isinstance(added, list):
                    for folder in added:
                        if isinstance(folder, dict) and isinstance(folder.get("uri"), str):
                            try:
                                p = url_to_file_path(folder["uri"])
                            except UrlParseError:
                                p = None
                            if p is not None:
                                ws = get_workspace(p)
                                if ws is not None:
                                    self.backend.add_workspace(ws)
                                    added_any = True
                if added_any:
                    self.backend.analyze_async()
        except Exception:
            pass

